import{_ as s,C as l,o as d,c as h,a2 as o,b as r,w as e,a as i,E as c,a3 as n}from"./chunks/framework.CZqXuAiL.js";const P=JSON.parse('{"title":"Configuration Reference","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/user-guide/configuration.md","filePath":"openshield-xdp/user-guide/configuration.md","lastUpdated":1785481554000}'),p={name:"openshield-xdp/user-guide/configuration.md"};function b(u,t,f,m,_,g){const a=l("Mermaid");return d(),h("div",null,[t[2]||(t[2]=o('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Runtime configuration file: <code>/etc/openshield/openshield.yaml</code></p><p>All defaults shown below match the actual code defaults from <code>userspace/internal/config/defaults.go</code>. Generate a fresh config with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span></span></code></pre></div><h2 id="top-level" tabindex="-1">Top-level <a class="header-anchor" href="#top-level" aria-label="Permalink to &quot;Top-level&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>interface</code></td><td><code>eno1</code></td><td>Network interface to attach XDP to</td></tr><tr><td><code>xdp_mode</code></td><td><code>auto</code></td><td>XDP attachment mode: <code>auto</code>, <code>native</code>, <code>generic</code>, <code>skb</code></td></tr></tbody></table><p><code>auto</code> tries native → generic → skb in fallback order. Set explicitly to force a specific mode.</p><h2 id="static-—-per-ip-rate-thresholds-scoring" tabindex="-1"><code>static</code> — Per-IP rate thresholds &amp; scoring <a class="header-anchor" href="#static-—-per-ip-rate-thresholds-scoring" aria-label="Permalink to &quot;`static` — Per-IP rate thresholds &amp; scoring&quot;">​</a></h2><p>Controls per-source-IP rate limiting with a suspicion scoring system. Each violation type adds score points; when cumulative score exceeds <code>suspicion_threshold</code>, the IP is banned.</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>bool</td><td>Master switch for per-IP static mitigation</td></tr><tr><td><code>pps_threshold</code></td><td><code>850</code></td><td>int</td><td>Max packets/s per IP (all protocols)</td></tr><tr><td><code>bps_threshold</code></td><td><code>8912896</code></td><td>int</td><td>Max bytes/s per IP (~8.5 MB/s)</td></tr><tr><td><code>tcp_pps_threshold</code></td><td><code>680</code></td><td>int</td><td>Max TCP packets/s per IP</td></tr><tr><td><code>udp_pps_threshold</code></td><td><code>425</code></td><td>int</td><td>Max UDP packets/s per IP</td></tr><tr><td><code>icmp_pps_threshold</code></td><td><code>85</code></td><td>int</td><td>Max ICMP packets/s per IP</td></tr><tr><td><code>syn_pps_threshold</code></td><td><code>170</code></td><td>int</td><td>Max SYN packets/s per IP</td></tr><tr><td><code>suspicion_threshold</code></td><td><code>100</code></td><td>int</td><td>Cumulative suspicion score that triggers a ban</td></tr><tr><td><code>ban_duration</code></td><td><code>3600</code></td><td>int</td><td>Ban duration in seconds (1 hour)</td></tr><tr><td><code>pps_score</code></td><td><code>20</code></td><td>int</td><td>Score added for PPS threshold violation</td></tr><tr><td><code>bps_score</code></td><td><code>20</code></td><td>int</td><td>Score added for BPS threshold violation</td></tr><tr><td><code>tcp_pps_score</code></td><td><code>15</code></td><td>int</td><td>Score added for TCP PPS violation</td></tr><tr><td><code>udp_pps_score</code></td><td><code>15</code></td><td>int</td><td>Score added for UDP PPS violation</td></tr><tr><td><code>icmp_pps_score</code></td><td><code>25</code></td><td>int</td><td>Score added for ICMP PPS violation</td></tr><tr><td><code>syn_pps_score</code></td><td><code>30</code></td><td>int</td><td>Score added for SYN PPS violation</td></tr><tr><td><code>suspicion_decay</code></td><td><code>0.5</code></td><td>float</td><td>Score retention per window (0.5 = keep 50%)</td></tr><tr><td><code>rate_limit_mode</code></td><td><code>threshold</code></td><td>string</td><td><code>threshold</code> (scoring) or <code>token_bucket</code></td></tr><tr><td><code>token_rate</code></td><td><code>0</code></td><td>int</td><td>Tokens refilled/s per IP (token_bucket mode)</td></tr><tr><td><code>token_burst</code></td><td><code>0</code></td><td>int</td><td>Max burst tokens per IP (token_bucket mode)</td></tr><tr><td><code>enable_connection_tracking</code></td><td><code>true</code></td><td>bool</td><td>Drop blind SYN-ACK/RST/ACK (no prior SYN)</td></tr><tr><td><code>ct_syn_timeout_sec</code></td><td><code>30</code></td><td>int</td><td>Connection tracking SYN timeout</td></tr><tr><td><code>star_duration_multiplicators</code></td><td><code>[1,2,4,8,16,32]</code></td><td>[]int</td><td>Multipliers for repeat-offender escalating bans</td></tr><tr><td><code>star_decay_seconds</code></td><td><code>3600</code></td><td>int</td><td>Clean seconds before star rating drops</td></tr><tr><td><code>ban_subnets</code></td><td><code>[]</code></td><td>[]string</td><td>Subnets to ban in CIDR notation</td></tr><tr><td><code>auto_subnet_ban</code></td><td><code>false</code></td><td>bool</td><td>Auto-ban entire subnets when many IPs banned</td></tr><tr><td><code>auto_subnet_prefixes</code></td><td><code>[24]</code></td><td>[]int</td><td>Prefix lengths for auto subnet ban</td></tr><tr><td><code>subnet_ban_duration</code></td><td><code>7200</code></td><td>int</td><td>Ban duration for subnet bans (2 hours)</td></tr></tbody></table><h3 id="suspicion-scoring-explained" tabindex="-1">Suspicion scoring explained <a class="header-anchor" href="#suspicion-scoring-explained" aria-label="Permalink to &quot;Suspicion scoring explained&quot;">​</a></h3>',11)),(d(),r(n,null,{default:e(()=>[c(a,{id:"mermaid-462",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22Packet%20Received%22%5D%20--%3E%20B%7B%22PPS%20%3E%20threshold%3F%22%7D%0A%20%20%20%20B%20--%3E%7C%22yes%22%7C%20C%5B%22suspicion_score%20%2B%3D%20pps_score%22%5D%0A%20%20%20%20B%20--%3E%7C%22no%22%7C%20D%7B%22BPS%20%3E%20threshold%3F%22%7D%0A%20%20%20%20D%20--%3E%7C%22yes%22%7C%20E%5B%22suspicion_score%20%2B%3D%20bps_score%22%5D%0A%20%20%20%20D%20--%3E%7C%22no%22%7C%20F%5B%22Check%20next%20metric...%22%5D%0A%20%20%20%20C%20--%3E%20G%7B%22score%20%3E%20suspicion_threshold%3F%22%7D%0A%20%20%20%20E%20--%3E%20G%0A%20%20%20%20F%20--%3E%20H%5B%22Window%20Reset%3Cbr%2F%3Eevery%201%20second%22%5D%0A%20%20%20%20G%20--%3E%7C%22yes%22%7C%20I%5B%22%F0%9F%94%B4%20BAN%20IP%3Cbr%2F%3Eduration%3A%20ban_duration_sec%22%5D%0A%20%20%20%20G%20--%3E%7C%22no%22%7C%20J%5B%22Decay%20score%3Cbr%2F%3Esuspicion_decay_percent%22%5D%0A%20%20%20%20I%20--%3E%20K%5B%22Repeat%20offender%3F%3Cbr%2F%3Enext%20ban%20threshold%20%3D%20lower%22%5D%0A%20%20%20%20J%20--%3E%20H%0A%20%20%20%20H%20--%3E%20A%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=o('<h3 id="token-bucket-mode" tabindex="-1">Token bucket mode <a class="header-anchor" href="#token-bucket-mode" aria-label="Permalink to &quot;Token bucket mode&quot;">​</a></h3><p>Set <code>rate_limit_mode: token_bucket</code> to use a token-based approach instead of scoring. Each IP gets <code>token_burst</code> initial tokens, with <code>token_rate</code> tokens refilled per second. Packets consume 1 token each. When tokens are exhausted, the IP is rate-limited (not banned — packets are dropped until tokens refill).</p><h2 id="validation-—-packet-validation-filters" tabindex="-1"><code>validation</code> — Packet validation filters <a class="header-anchor" href="#validation-—-packet-validation-filters" aria-label="Permalink to &quot;`validation` — Packet validation filters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>filter_private</code></td><td><code>true</code></td><td>Drop packets with private/bogon source IPs</td></tr><tr><td><code>filter_bogon</code></td><td><code>true</code></td><td>Drop packets from bogon address ranges</td></tr><tr><td><code>filter_bogus_tcp</code></td><td><code>true</code></td><td>Drop packets with impossible TCP flag combinations</td></tr><tr><td><code>filter_malformed</code></td><td><code>true</code></td><td>Drop packets with malformed headers</td></tr><tr><td><code>drop_fragments</code></td><td><code>false</code></td><td>Drop fragmented IP packets (MF flag or non-zero fragment offset)</td></tr></tbody></table><h2 id="dynamic-—-advanced-detection-engine" tabindex="-1"><code>dynamic</code> — Advanced detection engine <a class="header-anchor" href="#dynamic-—-advanced-detection-engine" aria-label="Permalink to &quot;`dynamic` — Advanced detection engine&quot;">​</a></h2><p>Adaptive baseline, attack detection, new-source flood prevention, amplification detection, and panic circuit breaker.</p><h3 id="baseline-learning" tabindex="-1">Baseline learning <a class="header-anchor" href="#baseline-learning" aria-label="Permalink to &quot;Baseline learning&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Enable dynamic detection engine</td></tr><tr><td><code>baseline_window</code></td><td><code>60</code></td><td>Seconds to build initial traffic baseline</td></tr><tr><td><code>baseline_update_interval</code></td><td><code>5</code></td><td>Seconds between baseline EMA updates</td></tr><tr><td><code>baseline_alpha</code></td><td><code>0.1</code></td><td>EMA smoothing factor for baseline</td></tr><tr><td><code>baseline_alpha_min</code></td><td><code>0.05</code></td><td>Minimum EMA alpha (adaptive floor)</td></tr><tr><td><code>baseline_alpha_max</code></td><td><code>0.50</code></td><td>Maximum EMA alpha (adaptive ceiling)</td></tr><tr><td><code>baseline_alpha_variance_scale</code></td><td><code>0.1</code></td><td>How much variance adjusts alpha</td></tr></tbody></table><h3 id="spike-attack-detection" tabindex="-1">Spike &amp; attack detection <a class="header-anchor" href="#spike-attack-detection" aria-label="Permalink to &quot;Spike &amp; attack detection&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>spike_percentage</code></td><td><code>200</code></td><td>% above baseline that triggers spike detection (200 = 3× baseline)</td></tr><tr><td><code>spike_recovery_factor</code></td><td><code>0.7</code></td><td>Fraction of spike threshold below which attack state clears (must be &lt; 1.0)</td></tr><tr><td><code>spike_recovery_time</code></td><td><code>10</code></td><td>Seconds below recovery factor before clearing</td></tr><tr><td><code>attack_threshold_multiplier</code></td><td><code>0.5</code></td><td>Threshold multiplier during attack (0.5 = 50% of normal)</td></tr><tr><td><code>attack_pps_threshold</code></td><td><code>0</code></td><td>Global PPS to trigger attack state (0 = disabled, uses baseline)</td></tr><tr><td><code>attack_bps_threshold</code></td><td><code>0</code></td><td>Global BPS to trigger attack state (0 = disabled)</td></tr></tbody></table><h3 id="new-source-flood" tabindex="-1">New source flood <a class="header-anchor" href="#new-source-flood" aria-label="Permalink to &quot;New source flood&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>new_source_limit</code></td><td><code>100</code></td><td>New unique IPs/second before flood mode engages</td></tr><tr><td><code>new_source_ban_duration</code></td><td><code>30</code></td><td>Ban duration for new sources detected during flood</td></tr></tbody></table><h3 id="panic-circuit-breaker" tabindex="-1">Panic circuit breaker <a class="header-anchor" href="#panic-circuit-breaker" aria-label="Permalink to &quot;Panic circuit breaker&quot;">​</a></h3><p>When per-CPU packet rate exceeds <code>panic_pps_rate</code>, the panic breaker bulk-drops <code>panic_drop_ratio</code>% of packets before any map lookups — protecting the CPU from map contention under extreme load.</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>panic_pps_rate</code></td><td><code>200000</code></td><td>Per-CPU PPS that triggers panic breaker</td></tr><tr><td><code>panic_drop_ratio</code></td><td><code>80</code></td><td>% of packets to bulk-drop when in panic mode</td></tr><tr><td><code>panic_global_pps_threshold</code></td><td><code>5000000</code></td><td>Cross-CPU total PPS for coordinated panic</td></tr><tr><td><code>panic_coordination_enabled</code></td><td><code>true</code></td><td>Enable userspace cross-CPU panic coordination</td></tr></tbody></table><h3 id="amplification-detection" tabindex="-1">Amplification detection <a class="header-anchor" href="#amplification-detection" aria-label="Permalink to &quot;Amplification detection&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>dns_amplification_enabled</code></td><td><code>true</code></td><td>Drop DNS amplification responses (sport=53, QR=1)</td></tr><tr><td><code>dns_amplification_payload_min</code></td><td><code>512</code></td><td>Minimum UDP payload for DNS amp detection</td></tr><tr><td><code>udp_amplification_enabled</code></td><td><code>true</code></td><td>Drop UDP amplification on known amp ports</td></tr><tr><td><code>udp_amp_ports</code></td><td><code>[53,123,1900,11211,17,19,520,69]</code></td><td>Monitored UDP amplification ports</td></tr><tr><td><code>udp_amp_payload_min</code></td><td><code>[512,90,256,50,50,50,50,50]</code></td><td>Min payload per amp port</td></tr></tbody></table><h3 id="behavioral-anomaly-detection" tabindex="-1">Behavioral anomaly detection <a class="header-anchor" href="#behavioral-anomaly-detection" aria-label="Permalink to &quot;Behavioral anomaly detection&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>syn_fin_ratio_enabled</code></td><td><code>true</code></td><td>Detect abnormal SYN/FIN ratios</td></tr><tr><td><code>syn_fin_ratio_threshold</code></td><td><code>100</code></td><td>SYN/FIN ratio that triggers detection</td></tr><tr><td><code>entropy_spoof_enabled</code></td><td><code>true</code></td><td>Detect spoofed-source floods via entropy analysis</td></tr><tr><td><code>entropy_spoof_threshold</code></td><td><code>12</code></td><td>Entropy threshold for spoof detection</td></tr><tr><td><code>ttl_anomaly_enabled</code></td><td><code>true</code></td><td>Per-IP TTL deviation detection</td></tr><tr><td><code>ttl_expected</code></td><td><code>64</code></td><td>Expected initial TTL</td></tr><tr><td><code>ttl_tolerance</code></td><td><code>5</code></td><td>TTL deviation tolerance</td></tr><tr><td><code>pkt_anomaly_enabled</code></td><td><code>true</code></td><td>Detect anomalous packet sizes</td></tr><tr><td><code>pkt_size_min_threshold</code></td><td><code>64</code></td><td>Minimum expected packet size</td></tr><tr><td><code>pkt_size_max_threshold</code></td><td><code>1024</code></td><td>Maximum expected packet size</td></tr></tbody></table><h3 id="connection-rate-limiting" tabindex="-1">Connection rate limiting <a class="header-anchor" href="#connection-rate-limiting" aria-label="Permalink to &quot;Connection rate limiting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>conn_rate_enabled</code></td><td><code>true</code></td><td>Enable connection rate limiting</td></tr><tr><td><code>conn_rate_limit</code></td><td><code>5000</code></td><td>Max new connections/s per IP</td></tr></tbody></table><h3 id="auto-escalation" tabindex="-1">Auto-escalation <a class="header-anchor" href="#auto-escalation" aria-label="Permalink to &quot;Auto-escalation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>auto_escalation_enabled</code></td><td><code>true</code></td><td>Enable automatic subnet ban escalation</td></tr><tr><td><code>auto_escalation_threshold</code></td><td><code>5</code></td><td>Bans per /24 before subnet ban triggered</td></tr></tbody></table><h3 id="mac-filtering" tabindex="-1">MAC filtering <a class="header-anchor" href="#mac-filtering" aria-label="Permalink to &quot;MAC filtering&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>mac_filter_enabled</code></td><td><code>false</code></td><td>MAC address whitelist/blacklist</td></tr><tr><td><code>mac_filter_mode</code></td><td><code>0</code></td><td>Filter mode (0=disabled, 1=whitelist, 2=blacklist)</td></tr><tr><td><code>mac_filter_entries</code></td><td><code>[]</code></td><td>List of MAC addresses</td></tr></tbody></table><h3 id="synproxy" tabindex="-1">SYNPROXY <a class="header-anchor" href="#synproxy" aria-label="Permalink to &quot;SYNPROXY&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>synproxy_enabled</code></td><td><code>false</code></td><td>Cookie-based SYN flood mitigation</td></tr><tr><td><code>syn_pps_threshold</code></td><td><code>170</code></td><td>Per-IP SYN packets/sec before the rate-based SYN gate scores the source</td></tr></tbody></table><h3 id="l7-signature-drops" tabindex="-1">L7 signature drops <a class="header-anchor" href="#l7-signature-drops" aria-label="Permalink to &quot;L7 signature drops&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>l7_drop_signatures</code></td><td><code>null</code></td><td>List of L7 payload signatures to drop</td></tr></tbody></table><h2 id="whitelist-—-trusted-ips" tabindex="-1"><code>whitelist</code> — Trusted IPs <a class="header-anchor" href="#whitelist-—-trusted-ips" aria-label="Permalink to &quot;`whitelist` — Trusted IPs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Enable whitelist bypass</td></tr><tr><td><code>ips</code></td><td><code>[]</code></td><td>Array of trusted IPs that bypass all mitigation</td></tr></tbody></table><p>Whitelisted IPs skip all rate checks, validation, and detection. Their packets pass directly through.</p><h2 id="maps-—-bpf-map-sizing" tabindex="-1"><code>maps</code> — BPF map sizing <a class="header-anchor" href="#maps-—-bpf-map-sizing" aria-label="Permalink to &quot;`maps` — BPF map sizing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ip_stats_max</code></td><td><code>100000</code></td><td>Max entries in per-IP stats LRU hashmap</td></tr><tr><td><code>ban_max</code></td><td><code>50000</code></td><td>Max entries in ban LRU hashmap</td></tr><tr><td><code>whitelist_max</code></td><td><code>10000</code></td><td>Max entries in whitelist hashmap</td></tr><tr><td><code>event_buffer_size</code></td><td><code>262144</code></td><td>Ring buffer size for events (256 KB)</td></tr><tr><td><code>bloom_filter_enabled</code></td><td><code>true</code></td><td>Use Bloom filter for fast whitelist lookup</td></tr><tr><td><code>bloom_filter_size</code></td><td><code>150000</code></td><td>Bloom filter entry count</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Bloom filter</p><p>When <code>bloom_filter_enabled: true</code>, whitelist lookups first check a Bloom filter — a probabilistic data structure that can definitively say &quot;this IP is NOT in the whitelist&quot; in O(1) with no hashmap lookup. Only IPs that pass the Bloom filter are checked against the full hashmap, drastically reducing map lookup overhead under load.</p><p>This is handled inside the BPF fast path: the Bloom filter map is probed before the whitelist hashmap, avoiding unnecessary hashmap lookups for non-whitelisted traffic.</p></div><h2 id="telemetry-—-stats-logging" tabindex="-1"><code>telemetry</code> — Stats &amp; logging <a class="header-anchor" href="#telemetry-—-stats-logging" aria-label="Permalink to &quot;`telemetry` — Stats &amp; logging&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>poll_interval</code></td><td><code>1</code></td><td>Seconds between BPF map reads</td></tr><tr><td><code>event_rate_limit</code></td><td><code>100</code></td><td>Max events/s pushed to TUI/socket</td></tr><tr><td><code>top_offenders_count</code></td><td><code>20</code></td><td>Number of top offenders tracked</td></tr><tr><td><code>log_level</code></td><td><code>info</code></td><td>Log level: <code>debug</code>, <code>info</code>, <code>warn</code>, <code>error</code></td></tr><tr><td><code>snapshot_interval</code></td><td><code>1</code></td><td>Seconds between snapshot pushes to TUI</td></tr></tbody></table><h2 id="alerter-—-webhook-notifications" tabindex="-1"><code>alerter</code> — Webhook notifications <a class="header-anchor" href="#alerter-—-webhook-notifications" aria-label="Permalink to &quot;`alerter` — Webhook notifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>false</code></td><td>Enable webhook alerter</td></tr><tr><td><code>webhook_url</code></td><td><code>&quot;&quot;</code></td><td>Discord/Slack webhook URL</td></tr><tr><td><code>events</code></td><td><code>[]</code></td><td>Event types to alert on</td></tr></tbody></table><h2 id="kernel-feature-gate-behavior" tabindex="-1">Kernel feature gate behavior <a class="header-anchor" href="#kernel-feature-gate-behavior" aria-label="Permalink to &quot;Kernel feature gate behavior&quot;">​</a></h2><p>Some configuration fields depend on kernel features. OpenShield-XDP auto-detects available features at load time:</p>',41)),(d(),r(n,null,{default:e(()=>[c(a,{id:"mermaid-1530",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22Kernel%20Version%3Cbr%2F%3Euname%20-r%22%5D%20--%3E%20B%7B%22Kernel%20%E2%89%A5%206.10%3F%22%7D%0A%20%20%20%20B%20--%3E%7C%22yes%22%7C%20C%5B%22%E2%9C%85%20All%20Features%3Cbr%2F%3EGlobal%20Detect%20%2B%20Entropy%22%5D%0A%20%20%20%20B%20--%3E%7C%22no%22%7C%20D%7B%22Kernel%20%E2%89%A5%205.15%3F%22%7D%0A%20%20%20%20D%20--%3E%7C%22yes%22%7C%20E%5B%22%E2%9C%85%20Baseline%20%2B%20scalar%20SYNPROXY%22%5D%0A%20%20%20%20D%20--%3E%7C%22no%22%7C%20H%5B%22%E2%9A%A0%EF%B8%8F%20Unsupported%3Cbr%2F%3Eminimum%20kernel%205.15%22%5D%0A%20%20%20%20C%20--%3E%20I%5B%22Compile%20with%20all%20flags%22%5D%0A%20%20%20%20E%20--%3E%20J%5B%22Compile%20with%20SYNPROXY%20flag%22%5D%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[i(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=o('<p>Run <code>openshield status</code> after loading to see which features are active. Fields that can&#39;t be supported due to kernel limitations are silently disabled with no error — the program degrades gracefully rather than failing to load.</p><h2 id="runtime-safe-vs-read-only-fields" tabindex="-1">Runtime-safe vs read-only fields <a class="header-anchor" href="#runtime-safe-vs-read-only-fields" aria-label="Permalink to &quot;Runtime-safe vs read-only fields&quot;">​</a></h2><p>Fields marked as <strong>runtime-safe</strong> can be changed via <code>openshield reload</code> or the TUI Config screen without unloading the XDP program. Read-only fields require a full reload:</p><p><strong>Runtime-safe:</strong> All <code>static</code> thresholds, scores, ban duration, rate limit mode, <code>validation</code> flags, <code>dynamic</code> thresholds, <code>whitelist.enabled</code>, <code>bloom_filter_enabled</code></p><p><strong>Read-only:</strong> <code>interface</code>, <code>xdp_mode</code>, map sizes (<code>ip_stats_max</code>, <code>ban_max</code>, etc.), <code>baseline_window</code>, <code>baseline_alpha</code>, <code>poll_interval</code></p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/cli/commands">CLI Reference</a> · <a href="/pingless-studios-docs/openshield-xdp/detection-engine/overview">Detection Engine</a> · <a href="/pingless-studios-docs/openshield-xdp/user-guide/tui">TUI Guide</a> e_alpha<code>, </code>poll_interval`</p><h2 id="next-steps-1" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps-1" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/cli/commands">CLI Reference</a> · <a href="/pingless-studios-docs/openshield-xdp/detection-engine/overview">Detection Engine</a> · <a href="/pingless-studios-docs/openshield-xdp/user-guide/tui">TUI Guide</a></p>',9))])}const y=s(p,[["render",b]]);export{P as __pageData,y as default};
